'use strict';
const products=window.KATALOG;
const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.toLowerCase().replace(/đ/g,'dj').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const formatPrice=n=>new Intl.NumberFormat('sr-Latn-RS',{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2}).format(n);
const productLink=p=>'#proizvod='+encodeURIComponent(p.slug);
const categoryOrder=['Auto i moto','Elektronika','Kuća i kuhinja','Lepota i lična nega','Bašta i poljoprivreda','Sport i slobodno vreme','Kućni ljubimci'];
let category='',page=0,filtered=products;const pageSize=24;
const featureProducts=[products.find(p=>p.naziv.includes('Friteza')),products.find(p=>p.naziv.includes('Mini kompresor')),products.find(p=>p.naziv.includes('VGR V-003'))];
const lead=featureProducts[0];
$('#heroMain').href=productLink(lead);$('#heroMain').innerHTML=`<div><small>${escapeHtml(lead.kategorija)}</small><h3>${escapeHtml(lead.naziv)}</h3><span class="round" aria-hidden="true">↗</span></div><img src="${lead.pregledna_slika}" alt="${escapeHtml(lead.naziv)}" fetchpriority="high">`;
$('#heroBottom').innerHTML=featureProducts.slice(1).map(p=>`<a href="${productLink(p)}"><img src="${p.pregledna_slika}" alt="${escapeHtml(p.naziv)}"><div><small>${escapeHtml(p.kategorija)}</small><b>${escapeHtml(p.naziv)}</b></div></a>`).join('');
function categories(){const values=['',...categoryOrder];$('#categories').innerHTML=values.map(c=>`<button type="button" data-category="${escapeHtml(c)}" class="${category===c?'active':''}" aria-pressed="${category===c}">${escapeHtml(c||'Sve kategorije')}<span>${c?products.filter(p=>p.kategorija===c).length:products.length}</span></button>`).join('');}
function groups(){const subset=products.filter(p=>!category||p.kategorija===category),options=[...new Set(subset.map(p=>p.potkategorija+' › '+p.grupa))].sort((a,b)=>a.localeCompare(b,'sr-Latn'));$('#group').innerHTML='<option value="">Sve potkategorije</option>'+options.map(g=>`<option value="${escapeHtml(g)}">${escapeHtml(g)}</option>`).join('');}
function filter(){page=0;const q=normalize($('#search').value).trim(),group=$('#group').value;filtered=products.filter(p=>(!category||p.kategorija===category)&&(!group||p.potkategorija+' › '+p.grupa===group)&&(!q||q.split(/\s+/).every(word=>normalize(p.naziv+' '+p.sifra+' '+p.opis+' '+p.kategorija+' '+p.grupa).includes(word))));const sort=$('#sort').value;if(sort==='price-up')filtered.sort((a,b)=>a.cena-b.cena);if(sort==='price-down')filtered.sort((a,b)=>b.cena-a.cena);if(sort==='name')filtered.sort((a,b)=>a.naziv.localeCompare(b.naziv,'sr-Latn'));$('#reset').hidden=!category&&!q&&!group&&sort==='default';render();}
function render(){const start=page*pageSize,end=Math.min(start+pageSize,filtered.length);$('#count').textContent=filtered.length?`Prikaz ${start+1}–${end} od ${filtered.length} proizvoda`:'Nema proizvoda za izabranu pretragu';$('#grid').innerHTML=filtered.slice(start,end).map(p=>`<a class="product" href="${productLink(p)}" aria-label="${escapeHtml(p.naziv)}, ${formatPrice(p.cena)} RSD"><div class="product-image"><img src="${p.pregledna_slika}" alt="${escapeHtml(p.naziv)}" loading="lazy" decoding="async"><span class="arrow" aria-hidden="true">↗</span></div><div class="product-info"><span class="product-category">${escapeHtml(p.kategorija)}</span><h3>${escapeHtml(p.naziv)}</h3><div class="product-price">${formatPrice(p.cena)}<span>RSD</span></div></div></a>`).join('')||'<div class="empty"><h3>Nismo pronašli taj proizvod.</h3><p>Pokušajte sa kraćim nazivom, šifrom ili drugom kategorijom.</p><button class="text-button" data-reset>Prikaži sve proizvode</button></div>';$('#page').textContent=`${page+1} / ${Math.max(1,Math.ceil(filtered.length/pageSize))}`;$('#previous').disabled=page===0;$('#next').disabled=end>=filtered.length;}
function reset(){category='';$('#search').value='';$('#sort').value='default';categories();groups();filter();}
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;categories();groups();filter();});$('#search').addEventListener('input',filter);$('#group').addEventListener('change',filter);$('#sort').addEventListener('change',filter);$('#reset').addEventListener('click',reset);$('#grid').addEventListener('click',e=>{if(e.target.closest('[data-reset]'))reset()});
$('#previous').onclick=()=>{page--;render();$('#proizvodi').scrollIntoView({behavior:'smooth'})};$('#next').onclick=()=>{page++;render();$('#proizvodi').scrollIntoView({behavior:'smooth'})};
const dialog=$('#productDialog');
function closeProduct(){if(dialog.open)dialog.close();if(location.hash.startsWith('#proizvod='))history.replaceState(null,'',location.pathname+location.search);document.title='Katalog proizvoda';}
function showProduct(p){$('#detail').innerHTML=`<div class="detail-layout"><div class="detail-gallery"><a id="originalImage" href="${p.slike[0]}" target="_blank" rel="noopener" aria-label="Otvori veću fotografiju"><img id="mainImage" class="detail-main" src="${p.slike[0]}" alt="${escapeHtml(p.naziv)}"></a><div class="thumbs" aria-label="Fotografije proizvoda">${p.slike.map((s,i)=>`<button class="${i===0?'selected':''}" data-image="${s}" aria-label="Fotografija ${i+1}" aria-pressed="${i===0}"><img src="${s}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="detail-copy"><div class="product-category">${escapeHtml(p.kategorija)} / ${escapeHtml(p.grupa)}</div><h2 id="productTitle">${escapeHtml(p.naziv)}</h2><span class="sku">Šifra artikla: ${p.sifra}</span><div class="detail-price">${formatPrice(p.cena)}<span>RSD</span></div><p>${escapeHtml(p.kratak_opis)}</p><h3>O proizvodu</h3><p>${escapeHtml(p.opis)}</p><div class="detail-actions"><button data-copy="link">Kopiraj link proizvoda ↗</button><button data-copy="sku" data-sku="${p.sifra}">Kopiraj šifru</button></div></div></div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.title=p.naziv+' | Katalog proizvoda';}
function route(){if(!location.hash.startsWith('#proizvod=')){if(dialog.open)dialog.close();document.title='Katalog proizvoda';return;}let slug;try{slug=decodeURIComponent(location.hash.slice(10))}catch{return}const p=products.find(p=>p.slug===slug);if(p)showProduct(p);}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
$('#detail').addEventListener('click',async e=>{const image=e.target.closest('[data-image]');if(image){$('#mainImage').src=image.dataset.image;$('#originalImage').href=image.dataset.image;document.querySelectorAll('[data-image]').forEach(b=>{b.classList.toggle('selected',b===image);b.setAttribute('aria-pressed',String(b===image))})}const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy==='link'?location.href:copy.dataset.sku);toast(copy.dataset.copy==='link'?'Link proizvoda je kopiran.':'Šifra proizvoda je kopirana.')}catch{toast('Kopiranje nije dostupno. Označite i kopirajte šifru ručno.')}}});
$('#close').onclick=closeProduct;dialog.addEventListener('cancel',e=>{e.preventDefault();closeProduct()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProduct()}});window.addEventListener('hashchange',route);
categories();groups();filter();route();
